const KERN = new Map<string, number>(
  KERN_PAIRS.split(" ").map((t) => [t.slice(0, 2), Number(t.slice(2)) / 1000]),
);
const TRACK = -0.02;
const ASC = 0.969;
const DESC = 0.241;
const LINE = 1.08;
const DOT = 0.15;
const DOT_GAP = 0.05;

function textEm(text: string) {
  let w = 0;
  let prev = "";
  for (const ch of text) {
    const c = ch.charCodeAt(0);
    w += (c >= 32 && c <= 126 ? INTER_TIGHT_500[c - 32] : 580) / 1000 + TRACK;
    w += KERN.get(prev + ch) ?? 0;
    prev = ch;
  }
  return w;
}

/**
 * Width in em. Inter Tight uses the advance and kerning tables above;
 * another family is measured with canvas once it has loaded.
 */
function useTextEm(family: string): (text: string) => number {
  const custom = family !== inter.fontFamily;
  const [ready, setReady] = useState<string | null>(null);
  const [handle] = useState(() =>
    custom ? delayRender("point-expand: measuring") : null,
  );
  const released = useRef(false);
  useEffect(() => {
    if (!custom) return;
    let live = true;
    document.fonts
      .load(`500 100px "${family}"`)
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(family);
        if (handle !== null && !released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [custom, family, handle]);
  if (!custom || ready !== family) return textEm;
  const ctx = document.createElement("canvas").getContext("2d");
  if (!ctx) return textEm;
  ctx.font = `500 100px "${family}"`;
  return (text: string) =>
    ctx.measureText(text).width / 100 + TRACK * [...text].length;
}

function breakLines(
  text: string,
  maxEm: number,
  em: (text: string) => number = textEm,
) {
  const words = text.split(/\s+/).filter(Boolean);
  const total = em(words.join(" ")) + DOT_GAP + DOT;
  const count = Math.max(1, Math.ceil(total / maxEm));
  const greedy = (target: number) => {
    const lines: string[][] = [[]];
    for (const w of words) {
      const cur = lines[lines.length - 1];
      const next = [...cur, w].join(" ");
      if (cur.length && em(next) + DOT_GAP + DOT > target) lines.push([w]);
      else cur.push(w);
    }
    return lines;
  };
  let target = total / count;
  let lines = greedy(target);
  while (lines.length > count && target < maxEm) {
    target = Math.min(maxEm, target * 1.04);
    lines = greedy(target);
  }
  return lines;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={3}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function PointExpandBase({
  statements = [
    "Launch films used to take weeks.",
    "Now they take an afternoon.",
    "Copy, paste, render.",
  ],
  pulses = 2,
  stagger = 2,
  hold = 6,
  accent = "#3B5BFD",
  ink,
  background,
  fontFamily = inter.fontFamily,
  scale = 1,
  delay = 0,
  grain = true,
  speed = 1,
  theme = "dark",
}: PointExpandProps) {
  const glide = useGlide();
  const frame = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width, height } = useVideoConfig();
  const p = PALETTES[theme];
  const stage =
    background === "transparent" ? "transparent" : (background ?? p.stage);
  // the full stop is filled with the next scene's colour; it needs a real one
  const dotStage = background === "transparent" ? p.stage : stage;
  const em = useTextEm(fontFamily);
  // the scaled position of a full stop, so the next scene grows from where it is drawn
  const at = (pt: { x: number; y: number; r: number }) =>
    scale === 1
      ? pt
      : {
          x: width / 2 + (pt.x - width / 2) * scale,
          y: height / 2 + (pt.y - height / 2) * scale,
          r: pt.r * scale,
        };
  const list = (statements.length ? statements : [""]).slice(0, 5);
  const count = list.length;

  const portrait = height > width * 1.1;
  const s = portrait
    ? (width / 1280) * 1.5
    : Math.min(width / 1280, height / 720);
  const maxW = width * (portrait ? 0.84 : 0.78);
  const baseFs = (portrait ? 112 : 108) * s;

  const scenes = list.map((raw, k) => {
    const text = raw.trim().replace(/[.。]+$/, "");
    const cap = portrait ? 3 : 2;
    let fs = baseFs;
    let lines = breakLines(text, maxW / fs, em);
    for (let i = 0; i < 10 && lines.length > cap; i++) {
      fs *= 0.9;
      lines = breakLines(text, maxW / fs, em);
    }
    const lh = fs * LINE;
    const top = (height - lines.length * lh) / 2;
    const baseline = ((LINE - (ASC + DESC)) / 2 + ASC) * fs;
    const rows = lines.map((words, li) => {
      const t = words.join(" ");
      const last = li === lines.length - 1;
      const w = (em(t) + (last ? DOT_GAP + DOT : 0)) * fs;
      return { words, left: (width - w) / 2, w, y: top + li * lh };
    });
    const lastRow = rows[rows.length - 1];
    const r = (DOT * fs) / 2;
    const point = {
      x: lastRow.left + lastRow.w - r,
      y: lastRow.y + baseline - r - fs * 0.002,
      r,
    };
    const beam = k % 2 === 1;
    return { text, fs, lh, rows, point, beam };
  });

  const RISE = 14;
  const STAGGER = stagger;
  const HOLD = hold;
  const PULSE = 7;
  const EXPAND = 18;
  const starts: number[] = [];
  const expands: number[] = [];
  let t = 2;
  for (let k = 0; k < count; k++) {
    starts.push(t);
    const words = scenes[k].rows.reduce((m, r) => m + r.words.length, 0);
    const landed = t + RISE + (words - 1) * STAGGER;
    const expandAt = landed + HOLD + pulses * PULSE;
    expands.push(expandAt);
    t = expandAt + EXPAND * 0.5;
  }
  const radius = (k: number) => {
    if (k === 0) return Number.POSITIVE_INFINITY;
    const point = at(scenes[k - 1].point);
    const far = Math.max(
      Math.hypot(point.x, point.y),
      Math.hypot(width - point.x, point.y),
      Math.hypot(point.x, height - point.y),
      Math.hypot(width - point.x, height - point.y),
    );
    const e = interpolate(
      frame,
      [expands[k - 1], expands[k - 1] + EXPAND],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_EXPAND,
      },
    );
    if (e <= 0) return 0;
    return point.r + (far + 4 - point.r) * e;
  };

  const pointFill = (k: number) => {
    if (k === count - 1) return scenes[k].beam ? dotStage : accent;
    return scenes[k + 1].beam ? accent : dotStage;
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      {scenes.map((sc, k) => {
        const r = radius(k);
        if (r <= 0.5) return null;
        if (k + 1 < count && radius(k + 1) > Math.hypot(width, height) * 1.5)
          return null;
        const origin = k > 0 ? at(scenes[k - 1].point) : null;
        const fg = sc.beam ? p.beamFg : (ink ?? p.stageFg);
        const sinkAt = (f: number) =>
          k + 1 < count
            ? interpolate(f, [expands[k], expands[k] + EXPAND], [0, 1], {
                ...CLAMP,
                easing: EASE_EXPAND,
              })
            : 0;
        const settleAt = (f: number) =>
          Math.max(
            0,
            interpolate(f, [starts[k] - 4, starts[k] + 40], [1, 0], {
              ...CLAMP,
              easing: EASE_OUT,
            }),
          );
        const sink = sinkAt(frame);
        const settle = settleAt(frame);
        const copyScaleAt = (f: number) =>
          (1 - sinkAt(f) * 0.05 + settleAt(f) * 0.02).toFixed(4);
        const copyScale = copyScaleAt(frame);
        const copyMoving =
          copyScale !== copyScaleAt(frame - 1) ||
          copyScale !== copyScaleAt(frame + 1);
        const ox = origin ? origin.x : width / 2;
        const oy = origin ? origin.y : height / 2;
        const ground = sc.beam
          ? [
              `radial-gradient(circle at ${ox}px ${oy}px, ${accent} 0%, color-mix(in oklab, ${BEAM[2]} 85%, ${accent}) ${(0.12 * width).toFixed(0)}px, ${BEAM[3]} ${(0.62 * width).toFixed(0)}px, #0b0a2e ${(1.1 * width).toFixed(0)}px)`,
              `radial-gradient(60% 60% at 50% 120%, color-mix(in oklab, ${BEAM[1]} 28%, transparent) 0%, transparent 70%)`,
            ].join(", ")
          : origin
            ? `radial-gradient(circle at ${ox}px ${oy}px, color-mix(in oklab, ${accent} ${theme === "dark" ? 16 : 10}%, ${stage}) 0%, ${stage} ${(0.7 * width).toFixed(0)}px)`
            : stage;
        const words = sc.rows.reduce((m, row) => m + row.words.length, 0);
        const landed = starts[k] + RISE + (words - 1) * STAGGER;
        const drop = interpolate(frame, [landed - 6, landed + 4], [0, 1], {
          ...CLAMP,
          easing: EASE_DROP,
        });
        const last = k === count - 1;
        const nPulses = last ? 1 : pulses;
        const pulseStart = landed + HOLD;
        let pulseScale = 1;
        const rings: { r: number; o: number }[] = [];
        for (let i = 0; i < nPulses; i++) {
          const a = pulseStart + i * PULSE;
          const u = interpolate(frame, [a, a + PULSE], [0, 1], CLAMP);
          if (u > 0 && u < 1)
            pulseScale += Math.sin(u * Math.PI) * (last ? 0.18 : 0.38);
          const ru = interpolate(frame, [a + 1, a + 1 + PULSE * 2.2], [0, 1], {
            ...CLAMP,
            easing: EASE_OUT,
          });
          if (ru > 0 && ru < 1)
            rings.push({ r: sc.point.r * (1.2 + 3.4 * ru), o: (1 - ru) * 0.7 });
        }
        const pre = last
          ? 1
          : 1 -
            0.18 *
              Math.sin(
                interpolate(
                  frame,
                  [expands[k] - 4, expands[k] + 2],
                  [0, 1],
                  CLAMP,
                ) * Math.PI,
              );
        const dotScale = (0.55 + 0.45 * drop) * pulseScale * pre;
        const fill = pointFill(k);
        return (
          <div
            key={k}
            style={{
              position: "absolute",
              inset: 0,
              clipPath: Number.isFinite(r)
                ? `circle(${r.toFixed(2)}px at ${ox.toFixed(2)}px ${oy.toFixed(2)}px)`
                : undefined,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                background: ground,
                transform: `scale(${(1 + settle * 0.04).toFixed(4)})`,
                transformOrigin: `${ox}px ${oy}px`,
              }}
            />
            {grain ? (
              <Grain
                opacity={sc.beam ? 0.07 : theme === "dark" ? 0.05 : 0.035}
              />
            ) : null}
            <ScaleLayer scale={scale}>
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  transform: `scale(${copyScale})${glide(copyMoving)}`,
                  transformOrigin: `${sc.point.x}px ${sc.point.y}px`,
                  opacity: 1 - sink * 0.35,
                }}
              >
                {(() => {
                  let wi = 0;
                  return sc.rows.map((row, li) => (
                    <div
                      key={li}
                      style={{
                        position: "absolute",
                        left: row.left,
                        top: row.y,
                        height: sc.lh,
                        lineHeight: `${sc.lh}px`,
                        fontFamily,
                        fontWeight: 500,
                        fontSize: sc.fs,
                        letterSpacing: `${TRACK}em`,
                        color: fg,
                        whiteSpace: "nowrap",
                        display: "flex",
                        fontVariantLigatures: "none",
                      }}
                    >
                      {row.words.map((w, j) => {
                        const idx = wi++;
                        const u = interpolate(
                          frame,
                          [
                            starts[k] + idx * STAGGER,
                            starts[k] + idx * STAGGER + RISE,
                          ],
                          [0, 1],
                          { ...CLAMP, easing: EASE_OUT },
                        );
                        return (
                          <span
                            key={j}
                            style={{
                              display: "inline-block",
                              overflow: "hidden",
                              height: sc.lh + sc.fs * 0.1,
                              paddingRight: "0.04em",
                              marginRight:
                                j < row.words.length - 1
                                  ? `${(em(" ") - 0.04).toFixed(3)}em`
                                  : "-0.04em",
                            }}
                          >
                            <span
                              style={{
                                display: "inline-block",
                                transform: `translateY(${((1 - u) * 118).toFixed(2)}%)${glide(midway(u) && !copyMoving)}`,
                              }}
                            >
                              {w}
                            </span>
                          </span>
                        );
                      })}
                    </div>
                  ));
                })()}
                <svg
                  width={width}
                  height={height}
                  style={{
                    position: "absolute",
                    inset: 0,
                    overflow: "visible",
                  }}
                  aria-hidden
                >
                  {rings.map((ring, i) => (
                    <circle
                      key={i}
                      cx={sc.point.x}
                      cy={sc.point.y}
                      r={ring.r}
                      fill="none"
                      stroke={fill}
                      strokeWidth={Math.max(1, 1.6 * s)}
                      opacity={ring.o}
                    />
                  ))}
                  {drop > 0 ? (
                    <circle
                      cx={sc.point.x}
                      cy={sc.point.y - (1 - drop) * sc.fs * 0.35}
                      r={sc.point.r * dotScale}
                      fill={fill}
                      opacity={Math.min(1, drop * 2)}
                    />
                  ) : null}
                </svg>
              </div>
            </ScaleLayer>
          </div>
        );
      })}
    </AbsoluteFill>
  );
}

