  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  accent: {
    type: "color",
    default: "#3B5BFD",
    description: "Accent",
  },
  pulses: {
    type: "number",
    default: 2,
    min: 0,
    max: 10,
    step: 1,
    description: "Pulses",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    default: 2,
    min: 0,
    max: 10,
    step: 1,
    description: "Word stagger",
    hiddenFromList: false,
  },
  hold: {
    type: "number",
    default: 6,
    min: 0,
    max: 40,
    step: 1,
