  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","accent","pulses","stagger","hold","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  accent: "#3B5BFD",
  pulses: 2,
  stagger: 2,
  hold: 6,
  fontFamily: "Inter Tight",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type PointExpandElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof PointExpandBase>;

const PointExpandInner = forwardRef<
  HTMLDivElement,
  PointExpandElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<PointExpand>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <PointExpandBase
          {...(componentProps as unknown as ComponentProps<typeof PointExpandBase>)}
        />
      </div>
    </Sequence>
  );
});

export const PointExpand = Interactive.withSchema({
  Component: PointExpandInner,
  componentName: "<PointExpand>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
